async function nativeOwner(p){return observeMain((E,id)=>{const w=E.webContents.fromId(id);if(!w||w.isDestroyed())throw Error('Exact own native WC lost');const roots=E.BaseWindow.getAllWindows().filter(r=>!r.isDestroyed()),describe=r=>{const children=r.contentView.children.map((v,index)=>({id:v.webContents?.id??null,url:v.webContents?.getURL?.()??'',visible:v.getVisible?.()??true,bounds:v.getBounds(),index}));if(r.webContents&&!r.webContents.isDestroyed()&&/\/out\/renderer\/index\.html/.test(r.webContents.getURL())&&!children.some(c=>c.id===r.webContents.id)){const b=r.getContentBounds();children.unshift({id:r.webContents.id,url:r.webContents.getURL(),visible:r.isVisible(),bounds:{x:0,y:0,width:b.width,height:b.height},index:-1});}return {id:r.id,visible:r.isVisible(),minimized:r.isMinimized(),opacity:r.getOpacity?.()??1,focusable:r.isFocusable?.()??true,children};};const all=roots.map(describe),mains=all.filter(r=>r.children.some(c=>/\/out\/renderer\/index\.html/.test(c.url)));if(mains.length!==1)throw Error('Unique private trusted shell required');const m=mains[0],shells=m.children.filter(c=>/\/out\/renderer\/index\.html/.test(c.url));if(shells.length!==1)throw Error('Unique native shell required');const shell=shells[0],placements=all.flatMap(r=>r.children.filter(c=>c.id===id).map(c=>({...c,parent:r.id,main:r.id===m.id,parentVisible:r.visible,opacity:r.opacity,focusable:r.focusable}))),front=m.children.filter(c=>c.index>shell.index&&c.visible&&c.bounds.width>0&&c.id!==null);return {id,wcUrl:w.getURL(),loading:w.isLoading(),shell,mainId:m.id,mainVisible:m.visible&&!m.minimized,placements,front,roots:all};},p.wc);}
 const parked=q=>q.mainVisible&&q.placements.length===1&&q.front.every(x=>x.id!==q.id)&&q.placements.every(x=>!x.visible||(x.main&&x.index<q.shell.index)||(!x.main&&x.opacity===0&&!x.focusable));

