async function grantUi(t,p){const view=await app.evaluate(js((selector,task,page)=>{const e=document.querySelector(selector),w=document.querySelector('.bw-workspace');if(!e||!w)return null;const rect=n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n);return {x:r.x,y:r.y,width:r.width,height:r.height,right:r.right,bottom:r.bottom,fontSize:s.fontSize,lineHeight:s.lineHeight,color:s.color,background:s.backgroundColor,borderWidth:s.borderWidth,borderColor:s.borderColor,borderRadius:s.borderRadius,padding:s.padding};};const ls=[...e.querySelectorAll('.bw-list > li')],b=[...e.querySelectorAll('button')];return {task:w.dataset.browserTask,page:w.dataset.browserPage??null,dialog:rect(e),workspace:rect(w),title:e.querySelector('h2')?.innerText,head:e.querySelector('.bw-dialog-head p')?.innerText,rows:ls.map(r=>({title:r.querySelector('strong')?.textContent,detail:r.querySelector('small')?.textContent,btn:r.querySelector('button')?.textContent,rect:rect(r),style:rect(r.querySelector('button'))})),buttons:b.map(r=>({text:r.textContent.trim(),aria:r.getAttribute('aria-label'),disabled:r.disabled,rect:rect(r)})),overflow:e.scrollWidth>e.clientWidth+2,preview:[...w.querySelectorAll('.bw-page-snapshot')].some(x=>x.complete&&x.naturalWidth>0)};},dialog,t.task,p.id));if(!view)return null;assert.equal(view.task,t.task);if(view.page)assert.equal(view.page,p.id);assert(view.title==='跨任务授权'&&view.head==='本次运行中你已允许的访问'&&view.rows.length===1&&view.rows[0].title===t.title+' → '+owned.target.title&&view.rows[0].detail==='WillYou 合成授权视觉测试 · 可以操作 · 仅本次运行'&&view.rows[0].btn==='撤销');assert(!view.overflow&&view.buttons.some(x=>x.text==='撤销'&&!x.disabled)&&view.buttons.some(x=>x.text==='完成'&&!x.disabled));const m=view.dialog,w=view.workspace;assert(m.x>=w.x-1&&m.y>=w.y-1&&m.right<=w.right+1&&m.bottom<=w.bottom+1,'Actual modal contained by right browser region');return view;}
async function captureGrant(t,theme,width){stage=currentSide+'-'+theme+'-rw'+width+'-win'+currentSize.join('x')+'-live-grant';await requireOriginalLiveGrant(t);await actualTheme(t.task,theme);await switchTask(t.task);await openPanel();let p=await awaitPage(t.task,t.page.url,t.page.id);assert.equal(p.wc,t.page.wc);await actualKeyboardWidth(width);p=await awaitPage(t.task,t.page.url,t.page.id);const before=await requireOriginalLiveGrant(t);await openGrantDialog();const measured=await until(async()=>{const q=await grantUi(t,p),o=await nativeOwner(p),g=await actualGeometry();if(!q||!parked(o)||!q.preview||g.theme!==theme||g.dpr!==currentDpr||JSON.stringify(g.inner)!==JSON.stringify(currentSize)||Math.abs(g.panel.width-width)>1||g.fonts!=='loaded')return null;return{q,o,g};},'same actual live original scope, modal and native containment',12000);const key=theme+'-rw'+width+'-win'+currentSize.join('x')+'|B11-grants-populated',label=currentSide+'-'+key.replace('|','-'),shell=await captureShell(label),still=await requireOriginalLiveGrant(t),after=await grantUi(t,p);assert(still&&still.grant.id===before.grant.id&&still.grant.runId===before.grant.runId);assert.deepEqual(after,measured.q);const row={side:currentSide,key,state:'B11-grants-populated',theme,width,size:currentSize.slice(),dpr:currentDpr,label,shell,native:null,ownership:measured.o,geometry:measured.g,ui:measured.q,before,after:still,passed:false,boundary:'Actual shell PNG and separate true parked native observation, no fake compositor; only actual live host grant, no target tools'};report.captures.push(row);await persist();await closeGrantDialog();const page=await awaitPage(t.task,t.page.url,t.page.id);assert.equal(page.wc,p.wc);return row;}
async function setupTargetSnapshot(t,label){await switchTask(t.task);await openPanel();const p=await awaitPage(t.task,targetUrl,t.page.id);const view=await exactNativePage(p,label);const marker=await observeMain(async(E,id,url)=>{const w=E.webContents.fromId(id);if(!w||w.isDestroyed()||w.getURL()!==url)throw Error('wrong owned target');return await w.executeJavaScript('({url:location.href, title:document.title, marker:document.body.innerText,epoch:performance.timeOrigin})');},p.wc,targetUrl);assert(marker.marker.includes('M16_VISUAL_APPROVAL_OWNED_STATIC'));return{logical:await checkTarget(),native:p,view,marker};}
